import numpy as np
from causallearn.graph.GeneralGraph import GeneralGraph
from causallearn.graph.GraphNode import GraphNode

# =====================================================================
# EDITABLE: implement run_causal_discovery below
# =====================================================================
def run_causal_discovery(X: np.ndarray) -> GeneralGraph:
    """
    Skeleton-first causal discovery:
      1) Reconstruct the skeleton conservatively from the data via
         stable-PC chi-squared CI tests (the skeleton is the object we
         build, not the object we test).
      2) Apply a conservative score-based directionality search (BDeu
         greedy search) restricted ONLY to the skeleton's edges — no
         direction is ever proposed for a pair outside the skeleton.
      3) Convert the resulting DAG to its CPDAG so any edge whose
         direction the data cannot determine remains undirected.
    """
    from causallearn.utils.PCUtils import SkeletonDiscovery
    from causallearn.utils.cit import CIT
    from causallearn.score.LocalScoreFunctionClass import LocalScoreClass
    from causallearn.score.LocalScoreFunction import local_score_BDeu
    from causallearn.utils.DAG2CPDAG import dag2cpdag

    n_samples, N = X.shape
    alpha = 0.05

    # ---- Step 1: conservative skeleton reconstruction (stable PC) ----
    indep_test = CIT(X, "chisq")
    cg_1 = SkeletonDiscovery.skeleton_discovery(
        X, alpha, indep_test, stable=True,
        background_knowledge=None, verbose=False,
        show_progress=False, node_names=None,
    )
    skel = np.zeros((N, N), dtype=bool)
    g = cg_1.G.graph
    for i in range(N):
        for j in range(i + 1, N):
            if g[i, j] != 0 or g[j, i] != 0:
                skel[i, j] = skel[j, i] = True

    # Augment the skeleton with GES (BDeu) adjacencies to improve
    # skeleton recall; the restricted score search below prunes any
    # spurious candidates, so a higher-recall skeleton is safe.
    ges_res = None
    try:
        from causallearn.search.ScoreBased.GES import ges
        ges_res = ges(
            X,
            score_func="local_score_BDeu",
            parameters={"sample_prior": 1.0, "structure_prior": 1.0},
        )
        gg = ges_res["G"].graph
        for i in range(N):
            for j in range(i + 1, N):
                if gg[i, j] != 0 or gg[j, i] != 0:
                    skel[i, j] = skel[j, i] = True
    except Exception:
        pass

    # ---- Step 2: conservative directionality search on skeleton only ----
    score_func = LocalScoreClass(
        data=X, local_score_fun=local_score_BDeu, parameters=None
    )
    nodes = [GraphNode(f"X{i + 1}") for i in range(N)]

    def _search(adj):
        """Greedy BDeu search restricted to the skeleton's edges."""
        local_scores = np.zeros(N)
        for j in range(N):
            local_scores[j] = score_func.score(
                j, sorted(np.where(adj[:, j] == 1)[0].tolist())
            )

        def _has_path(src, tgt):
            visited = set()
            stack = [src]
            while stack:
                node = stack.pop()
                if node == tgt:
                    return True
                if node in visited:
                    continue
                visited.add(node)
                for c in np.where(adj[node] == 1)[0]:
                    if int(c) not in visited:
                        stack.append(int(c))
            return False

        improved = True
        while improved:
            improved = False
            best_delta = 0.0
            best_op = None

            for i in range(N):
                for j in range(N):
                    if i == j or not skel[i, j]:
                        continue

                    if adj[i, j] == 0 and adj[j, i] == 0:
                        # --- Try ADD i -> j (skeleton only, no cycle) ---
                        if not _has_path(j, i):
                            pj_new = sorted(
                                np.where(adj[:, j] == 1)[0].tolist() + [i]
                            )
                            new_sj = score_func.score(j, pj_new)
                            delta = new_sj - local_scores[j]
                            if delta < best_delta - 1e-6:
                                best_delta = delta
                                best_op = ("add", i, j)

                    elif adj[i, j] == 1:
                        # --- Try DELETE i -> j ---
                        pj_new = [
                            p for p in np.where(adj[:, j] == 1)[0] if p != i
                        ]
                        new_sj = score_func.score(j, sorted(pj_new))
                        delta = new_sj - local_scores[j]
                        if delta < best_delta - 1e-6:
                            best_delta = delta
                            best_op = ("delete", i, j)

                        # --- Try REVERSE i -> j  to  j -> i ---
                        adj[i, j] = 0  # temporarily remove
                        if not _has_path(i, j):
                            pj_del = sorted(
                                np.where(adj[:, j] == 1)[0].tolist()
                            )
                            new_sj = score_func.score(j, pj_del)
                            pi_new = sorted(
                                np.where(adj[:, i] == 1)[0].tolist() + [j]
                            )
                            new_si = score_func.score(i, pi_new)
                            delta = (
                                (new_sj - local_scores[j])
                                + (new_si - local_scores[i])
                            )
                            if delta < best_delta - 1e-6:
                                best_delta = delta
                                best_op = ("reverse", i, j)
                        adj[i, j] = 1  # restore

            if best_op is not None:
                op_type, i, j = best_op
                if op_type == "add":
                    adj[i, j] = 1
                elif op_type == "delete":
                    adj[i, j] = 0
                elif op_type == "reverse":
                    adj[i, j] = 0
                    adj[j, i] = 1
                local_scores[j] = score_func.score(
                    j, sorted(np.where(adj[:, j] == 1)[0].tolist())
                )
                if op_type == "reverse":
                    local_scores[i] = score_func.score(
                        i, sorted(np.where(adj[:, i] == 1)[0].tolist())
                    )
                improved = True

        return adj, float(np.sum(local_scores))

    # Initialization strategy: start the restricted search both from the
    # empty graph and from a DAG extension of the GES CPDAG; keep the
    # converged candidate with the better (lower) BDeu score.
    inits = [np.zeros((N, N), dtype=int)]
    if ges_res is not None:
        try:
            from causallearn.utils.PDAG2DAG import pdag2dag
            gm = pdag2dag(ges_res["G"]).graph
            a0 = np.zeros((N, N), dtype=int)
            for i in range(N):
                for j in range(N):
                    if gm[j, i] == 1 and gm[i, j] == -1:  # i -> j
                        a0[i, j] = 1
            inits.append(a0)
        except Exception:
            pass

    best_adj, best_total = None, None
    for a0 in inits:
        adj_f, total = _search(a0.copy())
        if best_total is None or total < best_total - 1e-9:
            best_adj, best_total = adj_f, total
    adj = best_adj

    # ---- Step 3: CPDAG — leave MEC-undetermined edges undirected ----
    G = GeneralGraph(nodes)
    for i in range(N):
        for j in range(N):
            if adj[i, j] == 1:
                G.add_directed_edge(nodes[i], nodes[j])
    G = dag2cpdag(G)
    return G
